#[test]
fn hmac256() {
    // https://csrc.nist.gov/CSRC/media/Projects/Cryptographic-Standards-and-Guidelines/documents/examples/HMAC_SHA256.pdf
    fixture_init();

    let key64 = HmacAlgorithm::HMAC_SHA2_256
        .import_key(KEY64)
        .expect("key64/import");
    let res = HmacAlgorithm::HMAC_SHA2_256
        .hmac(&key64, b"Sample message for keylen=blocklen")
        .expect("key64/hmac");

    assert_eq!(
        res,
        [
            0x8b, 0xb9, 0xa1, 0xdb, 0x98, 0x6, 0xf2, 0xd, 0xf7, 0xf7, 0x7b, 0x82, 0x13, 0x8c, 0x79,
            0x14, 0xd1, 0x74, 0xd5, 0x9e, 0x13, 0xdc, 0x4d, 0x1, 0x69, 0xc9, 0x5, 0x7b, 0x13, 0x3e,
            0x1d, 0x62
        ],
    );

    assert_eq!(
        res,
        hmac(
            &HmacAlgorithm::HMAC_SHA2_256,
            KEY64,
            b"Sample message for keylen=blocklen"
        )
        .expect("key64/old_hmac")
    );

    let key32 = HmacAlgorithm::HMAC_SHA2_256
        .import_key(KEY32)
        .expect("key32/import");
    let res = HmacAlgorithm::HMAC_SHA2_256
        .hmac(&key32, b"Sample message for keylen<blocklen")
        .expect("key32/hmac");

    assert_eq!(
        res,
        [
            0xa2, 0x8c, 0xf4, 0x31, 0x30, 0xee, 0x69, 0x6a, 0x98, 0xf1, 0x4a, 0x37, 0x67, 0x8b,
            0x56, 0xbc, 0xfc, 0xbd, 0xd9, 0xe5, 0xcf, 0x69, 0x71, 0x7f, 0xec, 0xf5, 0x48, 0xf, 0xe,
            0xbd, 0xf7, 0x90
        ]
    );

    assert_eq!(
        res,
        hmac(
            &HmacAlgorithm::HMAC_SHA2_256,
            KEY32,
            b"Sample message for keylen<blocklen"
        )
        .expect("key32/old_hmac")
    );

    let key100 = HmacAlgorithm::HMAC_SHA2_256
        .import_key(KEY100)
        .expect("key100/import");
    let res = HmacAlgorithm::HMAC_SHA2_256
        .hmac(&key100, b"Sample message for keylen=blocklen")
        .expect("key100/hmac");

    assert_eq!(
        res,
        [
            0xbd, 0xcc, 0xb6, 0xc7, 0x2d, 0xde, 0xad, 0xb5, 0x0, 0xae, 0x76, 0x83, 0x86, 0xcb,
            0x38, 0xcc, 0x41, 0xc6, 0x3d, 0xbb, 0x8, 0x78, 0xdd, 0xb9, 0xc7, 0xa3, 0x8a, 0x43,
            0x1b, 0x78, 0x37, 0x8d
        ]
    );

    assert_eq!(
        res,
        hmac(
            &HmacAlgorithm::HMAC_SHA2_256,
            KEY100,
            b"Sample message for keylen=blocklen"
        )
        .expect("key100/old_hmac")
    );
}

#[test]
fn hmac384() {
    // https://csrc.nist.gov/CSRC/media/Projects/Cryptographic-Standards-and-Guidelines/documents/examples/HMAC_SHA384.pdf
    fixture_init();

    let key128 = HmacAlgorithm::HMAC_SHA2_384
        .import_key(KEY128)
        .expect("key128/import");
    let res = HmacAlgorithm::HMAC_SHA2_384
        .hmac(&key128, b"Sample message for keylen=blocklen")
        .expect("key128/hmac");

    assert_eq!(
        res,
        [
            0x63, 0xc5, 0xda, 0xa5, 0xe6, 0x51, 0x84, 0x7c, 0xa8, 0x97, 0xc9, 0x58, 0x14, 0xab,
            0x83, 0x0b, 0xed, 0xed, 0xc7, 0xd2, 0x5e, 0x83, 0xee, 0xf9, 0x19, 0x5c, 0xd4, 0x58,
            0x57, 0xa3, 0x7f, 0x44, 0x89, 0x47, 0x85, 0x8f, 0x5a, 0xf5, 0x0c, 0xc2, 0xb1, 0xb7,
            0x30, 0xdd, 0xf2, 0x96, 0x71, 0xa9
        ],
    );

    assert_eq!(
        res,
        hmac(
            &HmacAlgorithm::HMAC_SHA2_384,
            KEY128,
            b"Sample message for keylen=blocklen"
        )
        .expect("key128/old_hmac")
    );
}

#[test]
